import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long A = Long.parseLong(st.nextToken());
        long B = Long.parseLong(st.nextToken());
        long C = Long.parseLong(st.nextToken());

        if (B <= C) {
            long gcdVal = gcd(A, B);
            System.out.println((A / gcdVal) + "/" + (B / gcdVal));
            return;
        }

        long bestIdx = -1;
        long s = 0;
        for (long i = 1; i <= C; i++) {
            long j = i * A / B;
            if (Math.abs(i * A - j * B) > Math.abs(i * A - (j + 1) * B))
                j++;
            if (bestIdx == -1 || Math.abs(i * A - bestIdx * B) * i > Math.abs(i * A - j * B) * s) {
                bestIdx = j;
                s = i;
            }
        }
        System.out.println(bestIdx + "/" + s);
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
